const request = require('request');

const options = {
  method: 'GET',
  url: 'http://localhost:8080/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/file_processors/preprocess/%7Bitem_type%7D/%7Bitem_id%7D',
  qs: {attachment_id: 'SOME_STRING_VALUE', no_previews: 'SOME_BOOLEAN_VALUE'}
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("http://localhost:8080/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/file_processors/preprocess/%7Bitem_type%7D/%7Bitem_id%7D?attachment_id=SOME_STRING_VALUE&no_previews=SOME_BOOLEAN_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

